"""The busy cursor: the shell's shape turning, rasterised to Xcursor images."""

from __future__ import annotations

import struct
import unittest

from vitrail import spinner

# Generated by kit/shapes.js (node) and pinned here: the Python mirror must
# not drift from the component the shell draws.
CLOVER4_32 = (
    "M 13.12 3.41 Q 16 0 18.88 3.41 L 18.88 3.41 Q 21.76 10.24 28.59 13.12 "
    "L 28.59 13.12 Q 32 16 28.59 18.88 L 28.59 18.88 Q 21.76 21.76 18.88 28.59 "
    "L 18.88 28.59 Q 16 32 13.12 28.59 L 13.12 28.59 Q 10.24 21.76 3.41 18.88 "
    "L 3.41 18.88 Q 0 16 3.41 13.12 L 3.41 13.12 Q 10.24 10.24 13.12 3.41 Z"
)
SQUARE_32 = "M 22.4 0 Q 32 0 32 9.6 L 32 22.4 Q 32 32 22.4 32 L 9.6 32 Q 0 32 0 22.4 L 0 9.6 Q 0 0 9.6 0 Z"
TRIANGLE_24 = "M 7.49 4.84 Q 12 0 16.51 4.84 L 22.52 15.25 Q 24 23.06 18.01 23.06 L 5.99 23.06 Q 0 23.06 1.48 15.25 Z"


class PathTests(unittest.TestCase):
    def test_the_geometry_matches_the_shell_library(self) -> None:
        self.assertEqual(spinner.path("clover4", 32), CLOVER4_32)
        self.assertEqual(spinner.path("square", 32), SQUARE_32)
        self.assertEqual(spinner.path("triangle", 24), TRIANGLE_24)

    def test_an_unknown_shape_falls_back_to_the_circle(self) -> None:
        self.assertEqual(spinner.path("nope", 32), spinner.path("circle", 32))


class FrameTests(unittest.TestCase):
    def test_a_frame_turns_the_shape_inside_the_box(self) -> None:
        svg = spinner.frame_svg("clover4", 32, 90, "#ff0000")
        self.assertIn('transform="rotate(90 16 16)"', svg)
        self.assertIn('fill="#ff0000"', svg)
        self.assertIn(CLOVER4_32, svg)

    def test_frames_are_one_image_per_step(self) -> None:
        size = 8

        def run(svg: str) -> bytes:
            return bytes((255, 0, 0, 255)) * (size * size)

        images = spinner.frames(size=size, count=12, delay=100, run=run)
        self.assertEqual(len(images), 12)
        self.assertEqual((images[0]["subtype"], images[0]["xhot"], images[0]["yhot"]), (8, 4, 4))
        self.assertEqual(images[0]["delay"], 100)
        self.assertEqual(struct.unpack("<I", images[0]["pixels"][:4])[0], 0xFFFF0000)

    def test_a_failed_render_yields_no_frames(self) -> None:
        self.assertEqual(spinner.frames(run=lambda svg: None), [])


class ArgbTests(unittest.TestCase):
    def test_alpha_is_premultiplied(self) -> None:
        # premultiplied ARGB 0x80800000 / 0xffff0000, little-endian words
        self.assertEqual(spinner._argb(bytes((255, 0, 0, 128))), bytes.fromhex("00008080"))
        self.assertEqual(spinner._argb(bytes((255, 0, 0, 255))), bytes.fromhex("0000ffff"))


if __name__ == "__main__":
    unittest.main()
